import { useState } from "react";
import { Eye, EyeOff } from "lucide-react";
import { Button } from "@/components/ui/button";

type OptionKey = "a" | "b" | "c" | "d";

interface questions {
  questionId: number;
  correctAnswer: "a" | "b" | "c" | "d";
  discount: number;
  value: number;
  answers: { a: boolean; b: boolean; c: boolean; d: boolean };
}

const IMAGE_64 =
  "";

const OPTIONS: OptionKey[] = ["a", "b", "c", "d"];

function makeAnswers(count: number): questions[] {
  const rawWeights = Array.from({ length: count }, () => Math.random());
  const total = rawWeights.reduce((s, w) => s + w, 0);
  const values = rawWeights.map((w) => Math.round((w / total) * 200) / 10);
  const drift = Math.round((20 - values.reduce((s, v) => s + v, 0)) * 10) / 10;
  values[values.length - 1] =
    Math.round((values[values.length - 1] + drift) * 10) / 10;

  return Array.from({ length: count }, (_, i) => ({
    questionId: i + 1,
    discount: 25,
    value: values[i],
    correctAnswer: OPTIONS[Math.floor(Math.random() * 4)],
    answers: {
      a: Math.random() > 0.5,
      b: Math.random() > 0.5,
      c: Math.random() > 0.5,
      d: Math.random() > 0.5,
    },
  }));
}

